(() => {
'use strict';
const $=s=>document.querySelector(s), KEY='toeic700.studio.v1';
const icons={home:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',reading:'<path d="M12 6c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1Z"/><path d="M12 6v15"/>',listening:'<path d="M4 14v-3a8 8 0 0 1 16 0v3"/><rect x="3" y="12" width="4" height="8" rx="2"/><rect x="17" y="12" width="4" height="8" rx="2"/>',vocabulary:'<rect x="5" y="5" width="15" height="16" rx="3"/><path d="M16 2H5a3 3 0 0 0-3 3v11M9 15l3-6 3 6m-5-2h4"/>',review:'<path d="M4 7v5h5M4 12a8 8 0 1 0 2-6"/>',stats:'<path d="M4 20V10m8 10V4m8 16v-7"/>',check:'<path d="m5 12 4 4L19 6"/>',play:'<path d="m9 5 11 7-11 7Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',sound:'<path d="m11 5-6 4H2v6h3l6 4V5Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',flag:'<path d="M5 21V3c5-4 9 4 14 0v11c-5 4-9-4-14 0"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18"/>',leaf:'<path d="M20 3C6 2 1 10 7 17S23 14 20 3ZM5 21l10-11"/>'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.spark}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateKey=(date=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);
const shiftDay=(key,n)=>{const d=new Date(key+'T12:00:00+08:00');d.setUTCDate(d.getUTCDate()+n);return dateKey(d)};
const fresh=()=>({version:1,goal:90,days:{},history:[],wrong:{},cards:{},created:dateKey()});
let state=fresh(), storageOK=true;
function normalize(value){if(!value||value.version!==1||!value.days||!Array.isArray(value.history)||!value.cards||!value.wrong)throw Error('無法辨識的備份格式');const next=fresh();next.goal=[30,60,90,120].includes(value.goal)?value.goal:90;next.created=/^\d{4}-\d{2}-\d{2}$/.test(value.created)?value.created:dateKey();Object.entries(value.days).forEach(([k,v])=>{if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&v&&Number.isFinite(v.seconds))next.days[k]={seconds:Math.max(0,Math.min(v.seconds,86400)),vocab:[...new Set((v.vocab||[]).filter(id=>BANK.vocabulary.some(c=>c.id===id)))],sets:[...new Set((v.sets||[]).filter(id=>[...BANK.reading,...BANK.listening].some(s=>s.id===id)))]}});next.history=value.history.filter(h=>h&&['reading','listening','vocabulary'].includes(h.kind)&&Number.isInteger(h.correct)&&Number.isInteger(h.total)&&h.total>0&&h.correct>=0&&h.correct<=h.total&&/^\d{4}-\d{2}-\d{2}$/.test(h.date)).slice(-5000);Object.entries(value.cards).forEach(([id,c])=>{if(BANK.vocabulary.some(v=>v.id===id)&&c&&/^\d{4}-\d{2}-\d{2}$/.test(c.due)&&Number.isInteger(c.stage)&&c.stage>=0&&c.stage<=5)next.cards[id]={stage:c.stage,due:c.due}});Object.entries(value.wrong).forEach(([key,w])=>{const source=BANK[w?.kind]?.find(s=>s.id===w?.id);if(source&&Number.isInteger(w.index)&&source.questions[w.index]&&key===`${w.kind}:${w.id}:${w.index}`)next.wrong[key]={kind:w.kind,id:w.id,index:w.index}});return next}
try{const raw=localStorage.getItem(KEY);if(raw)state=normalize(JSON.parse(raw))}catch(e){storageOK=false}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true}catch(e){storageOK=false;toast('瀏覽器無法儲存紀錄，請匯出備份以免遺失。')}}
function day(){const k=dateKey();return state.days[k]??(state.days[k]={seconds:0,vocab:[],sets:[]})}
const pct=(a,b)=>b?Math.round(a/b*100):0;
const accuracy=kind=>{const rows=state.history.filter(h=>!kind||h.kind===kind);return rows.length?pct(rows.reduce((a,h)=>a+h.correct,0),rows.reduce((a,h)=>a+h.total,0)):null};
const complete=id=>state.history.some(h=>h.id===id);
const dueCards=()=>BANK.vocabulary.filter(v=>state.cards[v.id]&&state.cards[v.id].due<=dateKey());
let view='home', filter='全部', search='', dueOnly=false, run=null, deck=null, focusRemaining=25*60,focusOn=false,lastActive=Date.now(), timerTicks=0;
const mainNames={home:['學習總覽','OVERVIEW'],reading:['閱讀練習','READING'],listening:['聽力練習','LISTENING'],vocabulary:['單字複習','VOCABULARY'],review:['錯題筆記','REVIEW'],stats:['學習紀錄','YOUR PROGRESS'],quiz:['專注練習','PRACTICE'],flash:['單字練習','FLASHCARDS']};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function halt(){const a=$('#speech-audio');if(a)a.pause();if('speechSynthesis'in window)speechSynthesis.cancel()}
function nav(page){halt();view=page;filter='全部';search='';dueOnly=false;render();window.scrollTo({top:0,behavior:'instant'})}
function shell(content){const active=view==='quiz'?run?.kind:view==='flash'?'vocabulary':view;return `<aside class="sidebar"><a href="#home" class="brand" data-nav="home"><span class="brand-icon">${icon('leaf')}</span><span>lingo<span class="brand-dot">.</span><small>TOEIC 700 練習室</small></span></a><p class="nav-caption">你的學習空間</p><nav aria-label="主選單">${[['home','學習總覽'],['reading','閱讀練習'],['listening','聽力練習'],['vocabulary','單字複習'],['review','錯題筆記'],['stats','學習紀錄']].map(([id,label])=>`<button class="nav-item ${active===id?'active':''}" data-nav="${id}">${icon(id)}<span>${label}</span>${id==='review'&&Object.keys(state.wrong).length?`<span class="nav-count">${Object.keys(state.wrong).length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-goal"><span class="goal-art">${icon('flag')}</span><span class="eyebrow">一步一步，靠近目標</span><strong>下一站，700 分</strong><p>每天一點進步，<br>讓英文成為你的底氣。</p><div class="goal-tags"><span>8 週計畫</span><span>每日 ${state.goal} 分鐘</span></div></div><div class="sidebar-bottom"><span class="avatar">Y</span><span>我的學習帳本<small>紀錄儲存於此瀏覽器</small></span><span class="local-dot" title="本機儲存"></span></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">我的學習空間 <span>/</span> <strong>${mainNames[view][0]}</strong></div><div class="top-actions"><span class="date">${icon('calendar')}${new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',month:'long',day:'numeric',weekday:'short'}).format(new Date())}</span><button class="focus-button ${focusOn?'running':''}" data-action="focus" title="切換25分鐘專注計時">${icon('clock')}<span id="focus-label">${focusOn?'專注中':'專注計時'} ${String(Math.floor(focusRemaining/60)).padStart(2,'0')}:${String(Math.floor(focusRemaining%60)).padStart(2,'0')}</span></button></div></header><main id="main" tabindex="-1">${!storageOK?'<div class="storage-warning">目前未能讀取或儲存本機紀錄，請至學習紀錄匯出備份。</div>':''}${content}</main><footer>每天進步一點，就離目標近一點。<span>原創多益風格練習 · 非 ETS 官方題庫 · 練習正確率不等同正式分數</span></footer></div>`}
function title(kicker,title,desc,aside=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="subtitle">${desc}</p></div>${aside}</div>`}
function nextSet(kind){return BANK[kind].find(s=>!complete(s.id))||BANK[kind][state.history.filter(h=>h.kind===kind).length%BANK[kind].length]}
function streak(){let n=0,k=dateKey();if(!state.days[k]||(!state.days[k].seconds&&!state.days[k].sets.length&&!state.days[k].vocab.length))k=shiftDay(k,-1);while(state.days[k]&&(state.days[k].seconds>0||state.days[k].sets.length||state.days[k].vocab.length)){n++;k=shiftDay(k,-1)}return n}
function weekChart(){return `<div class="week-chart">${Array.from({length:7},(_,i)=>{const k=shiftDay(dateKey(),i-6),minutes=Math.round((state.days[k]?.seconds||0)/60),label=new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',weekday:'short'}).format(new Date(k+'T12:00:00+08:00')).replace('週','');return `<div class="chart-column ${i===6?'today':''}"><span class="bar-value">${minutes}</span><div class="bar-track"><div class="bar" style="height:${Math.min(100,pct(minutes,state.goal))}%"></div></div><span class="day-label">${label}</span></div>`}).join('')}</div>`}
function home(){const d=day(),minutes=Math.floor(d.seconds/60),vCount=d.vocab.length,rDone=d.sets.some(id=>id.startsWith('r')),lDone=d.sets.some(id=>id.startsWith('l')),tasks=Number(rDone)+Number(lDone)+Number(vCount>=10),r=rDone?BANK.reading.find(s=>d.sets.includes(s.id)):nextSet('reading'),l=lDone?BANK.listening.find(s=>d.sets.includes(s.id)):nextSet('listening');return title('A LITTLE EVERY DAY','把今天的努力，變成明天的實力。','閱讀、聽力、單字，一起朝多益 700 分前進。',`<div class="target-pill">${icon('flag')}目標分數 <strong>700</strong></div>`)+`<section class="hero"><div class="hero-content"><span class="hero-label"><span></span> YOUR DAILY ENGLISH ROUTINE</span><h2>今天，也為自己<br>累積一點英文力。</h2><p>從一組練習開始，找到自己的學習節奏。<br>你的每一步，我們都好好記下來。</p><button class="button light" data-action="daily">${icon('play')}開始今日練習</button><span class="hero-foot">${tasks}/3 項任務完成 · 每日計畫 ${state.goal} 分鐘</span></div><div class="hero-illustration" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="deco-star star-one">✦</span><span class="deco-star star-two">✦</span><div class="floating-word"><span class="word-dot"></span>Every day counts.</div><div class="illustration-book"><div class="book-spine"></div><span class="book-small">A LITTLE PROGRESS</span><strong>HELLO,<br>FUTURE<br>ME<span>✦</span></strong><div class="book-rule"></div><span class="book-bottom">ENGLISH FOR YOUR NEXT CHAPTER</span></div><div class="floating-score">${icon('check')}<div>今日任務<small>${tasks} / 3 已完成</small></div></div><div class="art-spark">✳</div></div></section><section class="metric-grid"><article class="metric"> <span class="metric-icon purple">${icon('clock')}</span><div><span>今日學習</span><strong>${minutes}<small> / ${state.goal} 分鐘</small></strong></div></article><article class="metric"><span class="metric-icon orange">${icon('spark')}</span><div><span>連續學習</span><strong>${streak()}<small> 天</small></strong></div></article><article class="metric"><span class="metric-icon green">${icon('vocabulary')}</span><div><span>已練習單字</span><strong>${Object.keys(state.cards).length}<small> / ${BANK.vocabulary.length} 個</small></strong></div></article><article class="metric"><span class="metric-icon blue">${icon('check')}</span><div><span>測驗正確率</span><strong>${accuracy()===null?'—':accuracy()+'%'}<small>${accuracy()===null?' 尚無紀錄':' 累計作答'}</small></strong></div></article></section><div class="section-heading"><div><h2>今天，想練習什麼？</h2><p>三種練習，讓英文能力穩穩向前。</p></div><span class="quiet-label">選擇你的學習模式</span></div><section class="module-grid">${[['reading','閱讀練習','READ & UNDERSTAND','從商務郵件到多篇閱讀，<br>練習找線索，讀懂真正的意思。','8 組題目 · 24 題','purple'],['listening','聽力練習','LISTEN & CONNECT','從日常對話到職場廣播，<br>讓耳朵跟上英文的節奏。','8 段音檔 · 24 題','orange'],['vocabulary','單字複習','WORDS THAT STICK','用例句理解，用間隔複習記住，<br>把單字變成用得上的能力。','60 個詞組 · 間隔複習','green']].map(([id,label,en,desc,info,color])=>`<article class="module-card ${color}"><div class="module-top"><span class="module-icon">${icon(id)}</span><span class="module-en">${en}</span></div><h3>${label}</h3><p>${desc}</p><div class="module-bottom"><span>${info}</span><button class="round-button" data-nav="${id}" aria-label="開始${label}">${icon('play')}</button></div></article>`).join('')}</section><section class="lower-grid"><article class="panel tasks-panel"><div class="section-heading"><h2>今日小目標</h2><span class="count-pill">${tasks} / 3</span></div>${[[vCount>=10,'vocabulary','複習 10 個單字',`${Math.min(vCount,10)} / 10 個`],[rDone,'reading',`完成一組閱讀`,r.title],[lDone,'listening','完成一組聽力',l.title]].map(([done,kind,label,sub])=>`<button class="task-row" data-task="${kind}"><span class="task-check ${done?'done':''}">${done?icon('check'):''}</span><span><strong>${label}</strong><small>${esc(sub)}</small></span><span class="task-status">${done?'已完成':'開始練習'}</span></button>`).join('')}</article><article class="panel week-panel"><div class="section-heading"><h2>本週的累積</h2><span class="quiet-label">分鐘 / 天</span></div>${weekChart()}<p class="chart-note">每一次開始，都值得被記錄。</p></article></section><div class="study-note">${icon('leaf')}<p><strong>今天的小提醒</strong>答對也別急著跳過。找出答案的依據，才是把練習變成實力的關鍵。</p></div>`}
function catalog(kind){const isRead=kind==='reading',sets=BANK[kind].filter(s=>filter==='全部'||s.level===filter);return title(isRead?'READ & UNDERSTAND':'LISTEN & CONNECT',isRead?'讀懂句子，也讀懂線索。':'讓耳朵，慢慢跟上英文。',isRead?'原創職場情境題組，作答後查看中文解析與答案依據。':'每段附英文合成語音，可變速、重播，作答後查看逐字稿。')+`<div class="toolbar"><div class="tabs" role="group" aria-label="難度篩選">${['全部','基礎','進階'].map(f=>`<button class="${filter===f?'selected':''}" data-filter="${f}">${f}</button>`).join('')}</div><span class="quiet-label">${BANK[kind].filter(s=>complete(s.id)).length} / ${BANK[kind].length} 組已完成</span></div><section class="exercise-grid">${sets.map((s,i)=>`<article class="panel exercise-card"><div class="exercise-top"><span class="exercise-icon ${isRead?'purple':'orange'}">${icon(kind)}</span><span class="tag">${s.level}</span></div><p class="eyebrow">${s.tag}</p><h2>${s.title}</h2><div class="exercise-meta"><span>${icon('clock')}${s.minutes}–${s.minutes+5} 分鐘</span><span>${s.questions.length} 題</span>${complete(s.id)?'<span class="completed-label">已完成</span>':''}</div><button class="button ${isRead?'primary':'warm'}" data-start="${kind}:${s.id}">${complete(s.id)?'再次練習':'開始練習'}${icon('play')}</button></article>`).join('')}</section>`}
function start(kind,id){halt();const s=BANK[kind].find(x=>x.id===id);if(!s)return;run={kind,id,answers:{},submitted:false,transcript:false};view='quiz';render();window.scrollTo(0,0)}
function quiz(){const s=BANK[run.kind].find(x=>x.id===run.id),listening=run.kind==='listening',answered=Object.keys(run.answers).length,correct=s.questions.reduce((n,q,i)=>n+Number(run.answers[i]===q.answer),0);return `<button class="back-link" data-nav="${run.kind}">返回${listening?'聽力':'閱讀'}列表</button>`+title(s.tag,s.title,`共 ${s.questions.length} 題 · ${s.level} · ${run.submitted?'已完成本次練習':'先獨立作答，再查看解析'}`)+`${run.submitted?`<div class="result-banner"><span class="result-check">${icon('check')}</span><div><h2>練習完成，累積一點新實力。</h2><p>答對 ${correct} / ${s.questions.length} 題 · 正確率 ${pct(correct,s.questions.length)}% · ${correct===s.questions.length?'本組全對，繼續保持！':'錯題已加入筆記'}</p></div><button class="button primary" data-action="next">下一組練習</button></div>`:''}<div class="quiz-layout"><article class="panel passage ${listening?'audio-panel':''}">${listening?`<div class="audio-art">${icon('listening')}<span class="audio-wave">▂ ▅ ▃ ▇ ▄ ▆ ▂ ▅ ▇ ▃ ▅ ▂</span></div><span class="eyebrow">LISTEN CLOSELY</span><h2>先聽一遍，抓住重點。</h2><p class="subtitle">可先看問題。練習時先使用正常速度，再針對漏聽處重播。</p><audio id="speech-audio" controls preload="metadata" src="audio/${s.id}.wav">此瀏覽器不支援音訊播放。</audio><div class="audio-tools"><label>播放速度 <select id="audio-rate"><option value="0.8">0.8 倍</option><option value="1" selected>1.0 倍</option><option value="1.2">1.2 倍</option></select></label><button class="text-button" data-action="replay">${icon('review')}重新播放</button></div><div id="audio-error" role="alert"></div><p class="audio-caption">英文合成語音 · 學習用途，不作正式口音模擬</p>${run.submitted?`<details open><summary>英文逐字稿</summary><div class="english transcript">${esc(s.transcript).replace(/\n/g,'<br><br>')}</div></details>`:'<div class="transcript-locked">'+icon('reading')+' 提交答案後，開啟逐字稿與中文解析。</div>'}`:`<div class="email-heading"><span class="mail-dot"></span><span>${esc(s.from)}</span></div><h2 class="english">${esc(s.subject)}</h2><div class="english passage-text">${esc(s.text).replace(/\n/g,'<br>')}</div>`}</article><section class="questions" aria-label="測驗題目">${s.questions.map((q,i)=>`<article class="panel question"><div class="question-heading"><span class="question-number">${String(i+1).padStart(2,'0')}</span><h3 class="english">${esc(q.q)}</h3></div><div class="options" role="group" aria-label="第${i+1}題選項">${q.options.map((o,j)=>`<button class="option ${run.answers[i]===j?'chosen':''} ${run.submitted?(q.answer===j?'correct':run.answers[i]===j?'incorrect':''):''}" data-answer="${i}:${j}" aria-pressed="${run.answers[i]===j}" ${run.submitted?'disabled':''}><span class="option-letter">${'ABCD'[j]}</span><span class="english">${esc(o)}</span>${run.submitted&&q.answer===j?icon('check'):''}</button>`).join('')}</div>${run.submitted?`<div class="explanation"><strong>${run.answers[i]===q.answer?'答對了':'再記住這個線索'} · 正確答案 ${'ABCD'[q.answer]}</strong><p>${esc(q.explain)}</p></div>`:''}</article>`).join('')}<div class="submit-row"><span>${run.submitted?'已儲存學習紀錄':`已作答 ${answered} / ${s.questions.length} 題`}</span>${!run.submitted?`<button class="button primary" data-action="submit" ${answered!==s.questions.length?'disabled':''}>提交答案 ${icon('check')}</button>`:`<button class="button primary" data-action="next">下一組練習 ${icon('play')}</button>`}</div></section></div>`}
function submitQuiz(){if(!run||run.submitted)return;const s=BANK[run.kind].find(x=>x.id===run.id);if(Object.keys(run.answers).length!==s.questions.length)return;run.submitted=true;let correct=0;s.questions.forEach((q,i)=>{const key=`${run.kind}:${s.id}:${i}`;if(run.answers[i]===q.answer){correct++;delete state.wrong[key]}else state.wrong[key]={kind:run.kind,id:s.id,index:i}});state.history.push({date:dateKey(),kind:run.kind,id:s.id,correct,total:s.questions.length});if(!day().sets.includes(s.id))day().sets.push(s.id);save();halt();render();window.scrollTo({top:0,behavior:'smooth'})}
function vocab(){const cards=BANK.vocabulary.filter(v=>(filter==='全部'||v.tag===filter)&&(!dueOnly||(state.cards[v.id]&&state.cards[v.id].due<=dateKey()))&&(!search||[v.word,v.meaning,v.phrase].some(t=>t.toLowerCase().includes(search.toLowerCase()))));return title('WORDS THAT STICK','把單字，變成你的日常。','先理解詞組與例句，再透過主動回想，讓記憶留得更久。')+`<div class="vocab-banner"><div><span class="eyebrow">SPACED REPETITION</span><h2>今天，有 ${dueCards().length} 個單字等你複習。</h2><p>記住後依序安排 1、3、7、14、30 天複習；忘記就重新開始。</p></div><div class="vocab-actions"><button class="button primary" data-action="flash">${icon('vocabulary')}翻卡練習</button><button class="button secondary" data-action="wordquiz">${icon('check')}單字測驗</button></div></div><div class="toolbar vocab-toolbar"><label class="search-field">${icon('search')}<input id="word-search" type="search" placeholder="搜尋英文、中文或詞組…" value="${esc(search)}" aria-label="搜尋單字"></label><label class="category-label">主題 <select id="word-filter">${['全部',...new Set(BANK.vocabulary.map(v=>v.tag))].map(t=>`<option ${filter===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="checkbox-label"><input type="checkbox" id="due-only" ${dueOnly?'checked':''}>只看到期單字</label></div><div class="section-heading"><h2>我的單字庫 <span class="inline-count">${cards.length}</span></h2><span class="quiet-label">每次練習最多 10 個，優先複習到期詞</span></div><div class="word-grid">${cards.map(v=>`<article class="panel word-card"><div><span class="tag">${v.tag}</span><button class="sound-button" data-speak="${v.id}" aria-label="播放 ${esc(v.word)} 發音">${icon('sound')}</button></div><h3 class="english">${esc(v.word)} <small>${v.pos}</small></h3><p>${v.meaning}</p><span class="phrase english">${esc(v.phrase)}</span><div class="word-status">${!state.cards[v.id]?'尚未練習':state.cards[v.id].due<=dateKey()?'今天複習':`下次複習 ${state.cards[v.id].due}`}</div></article>`).join('')||'<div class="empty-state">'+icon('search')+'<h2>沒有符合的單字</h2><p>試試其他關鍵字，或取消到期篩選。</p></div>'}</div>`}
function filteredDeck(){const list=BANK.vocabulary.filter(v=>(filter==='全部'||v.tag===filter)&&(!dueOnly||(state.cards[v.id]&&state.cards[v.id].due<=dateKey()))&&(!search||[v.word,v.meaning,v.phrase].some(t=>t.toLowerCase().includes(search.toLowerCase()))));return list.sort((a,b)=>{const rank=v=>!state.cards[v.id]?1:state.cards[v.id].due<=dateKey()?0:2;return rank(a)-rank(b)||(state.cards[a.id]?.due||'').localeCompare(state.cards[b.id]?.due||'')}).slice(0,10)}
function shuffle(arr){const out=arr.slice();for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out}
function startDeck(mode){const cards=filteredDeck();if(!cards.length){toast('目前篩選沒有可練習的單字。');return}halt();deck={mode,cards,index:0,revealed:false,correct:0,choices:[],answer:null,finished:false};prepareCard();view='flash';render();window.scrollTo(0,0)}
function prepareCard(){const v=deck.cards[deck.index];deck.revealed=false;deck.answer=null;deck.choices=shuffle([v,...shuffle(BANK.vocabulary.filter(w=>w.id!==v.id)).slice(0,3)])}
function recordCard(known){const v=deck.cards[deck.index],old=state.cards[v.id],stage=known?Math.min((old?.stage||0)+1,5):0;state.cards[v.id]={stage,due:shiftDay(dateKey(),known?[0,1,3,7,14,30][stage]:0)};if(!day().vocab.includes(v.id))day().vocab.push(v.id);save()}
function advanceCard(known){recordCard(known);if(known)deck.correct++;deck.index++;if(deck.index>=deck.cards.length){deck.finished=true;if(deck.mode==='quiz')state.history.push({date:dateKey(),kind:'vocabulary',id:'words-'+Date.now(),correct:deck.correct,total:deck.cards.length});save()}else prepareCard();render()}
function flash(){if(deck.finished)return `<div class="flash-wrap"><div class="panel deck-result"><span class="big-success">${icon('check')}</span><p class="eyebrow">A LITTLE PROGRESS</p><h1>又累積了 ${deck.cards.length} 個單字。</h1><p>${deck.mode==='quiz'?`本次答對 ${deck.correct} / ${deck.cards.length} 題`:`本次自評記住 ${deck.correct} 個，還需加強 ${deck.cards.length-deck.correct} 個`}，複習日期已安排好。</p><button class="button primary" data-nav="vocabulary">回到單字庫</button></div></div>`;const v=deck.cards[deck.index];return `<button class="back-link" data-nav="vocabulary">返回單字庫</button>`+title(deck.mode==='quiz'?'VOCABULARY QUIZ':'ACTIVE RECALL',deck.mode==='quiz'?'選出正確的意思。':'先回想，再翻開答案。',`第 ${deck.index+1} / ${deck.cards.length} 個單字`)+`<div class="deck-progress"><span style="width:${pct(deck.index,deck.cards.length)}%"></span></div><div class="flash-wrap"><article class="panel flash-card"><span class="tag">${v.tag}</span><button class="sound-button flash-sound" data-speak="${v.id}" aria-label="播放發音">${icon('sound')}</button><span class="eyebrow">${v.pos}</span><h2 class="english">${esc(v.word)}</h2>${deck.mode==='quiz'?`<div class="word-quiz-options">${deck.choices.map((w,i)=>`<button class="option ${deck.answer===i?'chosen':''} ${deck.answer!==null?(w.id===v.id?'correct':deck.answer===i?'incorrect':''):''}" data-word-answer="${i}" ${deck.answer!==null?'disabled':''}><span class="option-letter">${'ABCD'[i]}</span>${w.meaning}</button>`).join('')}</div>${deck.answer!==null?`<div class="card-answer"><strong>${v.meaning}</strong><p class="english">${esc(v.phrase)}</p><p class="english example">${esc(v.example)}</p></div><button class="button primary" data-action="wordnext">下一個單字</button>`:''}`:deck.revealed?`<div class="card-answer"><h3>${v.meaning}</h3><p class="english">${esc(v.phrase)}</p><p class="english example">${esc(v.example)}</p></div><p class="recall-note">剛才有想出正確意思嗎？誠實評估，複習才會有效。</p><div class="recall-actions"><button class="button secondary" data-action="forgot">還沒記住</button><button class="button primary" data-action="known">我記住了 ${icon('check')}</button></div>`:`<p class="recall-hint">試著說出中文意思，或想一個使用情境。</p><button class="button primary" data-action="reveal">翻開答案</button>`}</article><p class="quiet-label center">理解一個詞組，比匆匆看過十個單字更有價值。</p></div>`}
function review(){const wrong=Object.values(state.wrong);return title('LEARN FROM EVERY MISTAKE','錯過的，變成下次的把握。','答錯的閱讀與聽力題會保留在這裡；重做答對後，自動移出。')+`<div class="review-summary">${icon('review')}<span>目前有 <strong>${wrong.length}</strong> 題待加強</span><span class="quiet-label">單字複習另依記憶間隔安排</span></div>${wrong.length?`<div class="review-list">${wrong.map(w=>{const s=BANK[w.kind].find(s=>s.id===w.id),q=s.questions[w.index];return `<article class="panel review-card"><div><span class="tag">${w.kind==='reading'?'閱讀':'聽力'} · ${s.title}</span><h2 class="english">${esc(q.q)}</h2><details><summary>查看線索與答案</summary><p>${esc(q.explain)}</p><strong class="english">${'ABCD'[q.answer]}. ${esc(q.options[q.answer])}</strong></details></div><button class="button secondary" data-start="${w.kind}:${s.id}">重新練習</button></article>`}).join('')}</div>`:`<div class="empty-state panel">${icon('leaf')}<h2>這裡，等著收藏你的進步。</h2><p>完成練習後，需加強的題目會自動加入。</p><button class="button primary" data-nav="reading">開始一組閱讀</button></div>`}`}
function stats(){const totalSeconds=Object.values(state.days).reduce((n,d)=>n+d.seconds,0),history=state.history.slice(-20).reverse();return title('YOUR PROGRESS','每一次練習，都算數。','看見自己的累積，也找到下一步需要加強的地方。')+`<section class="metric-grid"><article class="metric"><span class="metric-icon purple">${icon('clock')}</span><div><span>累積學習時間</span><strong>${Math.floor(totalSeconds/60)}<small> 分鐘</small></strong></div></article><article class="metric"><span class="metric-icon orange">${icon('check')}</span><div><span>完成測驗</span><strong>${state.history.length}<small> 次</small></strong></div></article><article class="metric"><span class="metric-icon green">${icon('vocabulary')}</span><div><span>已練習單字</span><strong>${Object.keys(state.cards).length}<small> 個</small></strong></div></article><article class="metric"><span class="metric-icon blue">${icon('spark')}</span><div><span>連續學習</span><strong>${streak()}<small> 天</small></strong></div></article></section><div class="lower-grid"><article class="panel"><div class="section-heading"><h2>近七天學習</h2><span class="quiet-label">分鐘 / 天</span></div>${weekChart()}</article><article class="panel skill-panel"><h2>各項測驗正確率</h2>${[['reading','閱讀'],['listening','聽力'],['vocabulary','單字']].map(([kind,name])=>`<div class="skill-row"><span>${name}</span><div class="skill-track"><span style="width:${accuracy(kind)||0}%"></span></div><strong>${accuracy(kind)===null?'—':accuracy(kind)+'%'}</strong></div>`).join('')}<p class="quiet-label">包含重做紀錄；自評翻卡不計入測驗正確率。</p></article></div><article class="panel history-panel"><div class="section-heading"><h2>最近練習紀錄</h2><span class="quiet-label">最多顯示 20 筆</span></div>${history.length?`<div class="table-scroll"><table><thead><tr><th>日期</th><th>練習項目</th><th>答對 / 題數</th><th>正確率</th></tr></thead><tbody>${history.map(h=>`<tr><td>${esc(h.date)}</td><td>${h.kind==='vocabulary'?'單字測驗':esc(BANK[h.kind].find(s=>s.id===h.id)?.title||'練習')}</td><td>${h.correct} / ${h.total}</td><td><span class="score-pill">${pct(h.correct,h.total)}%</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-copy">尚無測驗紀錄。完成第一組練習，就從這裡看見進步。</p>'}</article><article class="panel settings-panel"><div><h2>我的學習設定</h2><p>紀錄只保存在目前的瀏覽器，不會自動同步到其他裝置。定期匯出備份，可在其他裝置匯入。</p><p class="quiet-label">時間僅計算頁面可見且最近有操作的時段；背景或閒置超過 2 分鐘暫停累積。</p></div><div class="settings-actions"><label>每日目標 <select id="goal-select">${[30,60,90,120].map(g=>`<option value="${g}" ${g===state.goal?'selected':''}>${g} 分鐘</option>`).join('')}</select></label><button class="button secondary" data-action="export">${icon('download')}匯出紀錄</button><label class="button secondary import-label">匯入備份<input id="import-file" type="file" accept="application/json,.json"></label></div><p id="import-status" role="status"></p></article>`}
function render(){const oldAudio=$('#speech-audio');const pages={home,catalog:()=>catalog(view),reading:()=>catalog('reading'),listening:()=>catalog('listening'),vocabulary:vocab,quiz,flash,review,stats};$('#app').innerHTML=shell(pages[view]());const newAudio=$('#speech-audio');if(oldAudio&&newAudio&&oldAudio.getAttribute('src')===newAudio.getAttribute('src')){newAudio.replaceWith(oldAudio);$('#audio-rate').value=String(oldAudio.playbackRate)}else{if(oldAudio)oldAudio.pause();if(newAudio)newAudio.addEventListener('error',()=>{const error=$('#audio-error');if(error)error.textContent='音檔無法載入，請檢查連線後重播。';})}document.title=`${mainNames[view][0]} · TOEIC 700 練習室`}
function speak(id){const v=BANK.vocabulary.find(v=>v.id===id);if(!v)return;if(!('speechSynthesis'in window)){toast('此瀏覽器不支援單字發音，請使用新版 Chrome、Edge 或 Safari。');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(v.word+'. '+v.phrase);u.lang='en-US';u.rate=.85;const voices=speechSynthesis.getVoices();u.voice=voices.find(x=>x.lang.startsWith('en-US'))||voices.find(x=>x.lang.startsWith('en'))||null;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('無法播放單字發音，請確認裝置已安裝英文語音。')};speechSynthesis.speak(u)}
document.addEventListener('click',e=>{lastActive=Date.now();const navEl=e.target.closest('[data-nav]');if(navEl){e.preventDefault();nav(navEl.dataset.nav);return}const startEl=e.target.closest('[data-start]');if(startEl){start(...startEl.dataset.start.split(':'));return}const filterEl=e.target.closest('[data-filter]');if(filterEl){filter=filterEl.dataset.filter;render();return}const ans=e.target.closest('[data-answer]');if(ans&&!run.submitted){const [i,j]=ans.dataset.answer.split(':').map(Number);const scroll=window.scrollY;run.answers[i]=j;render();document.querySelector('[data-answer=\"'+i+':'+j+'\"]')?.focus({preventScroll:true});window.scrollTo(0,scroll);return}const snd=e.target.closest('[data-speak]');if(snd){speak(snd.dataset.speak);return}const wa=e.target.closest('[data-word-answer]');if(wa&&deck.answer===null){deck.answer=Number(wa.dataset.wordAnswer);render();return}const task=e.target.closest('[data-task]');if(task){if(task.dataset.task==='vocabulary'){filter='全部';search='';dueOnly=false;startDeck('flash')}else{const s=nextSet(task.dataset.task);start(task.dataset.task,s.id)}return}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
switch(action){case'daily':if(day().vocab.length<10){filter='全部';search='';dueOnly=false;startDeck('flash')}else if(!day().sets.some(x=>x.startsWith('r'))){start('reading',nextSet('reading').id)}else if(!day().sets.some(x=>x.startsWith('l'))){start('listening',nextSet('listening').id)}else nav('review');break;case'submit':submitQuiz();break;case'next':{const list=BANK[run.kind],i=list.findIndex(x=>x.id===run.id);start(run.kind,list[(i+1)%list.length].id);break}case'replay':{const a=$('#speech-audio');a.currentTime=0;a.play().catch(()=>toast('音訊播放失敗，請點播放鍵再試一次。'));break}case'flash':startDeck('flash');break;case'wordquiz':startDeck('quiz');break;case'reveal':deck.revealed=true;render();break;case'known':advanceCard(true);break;case'forgot':advanceCard(false);break;case'wordnext':advanceCard(deck.choices[deck.answer].id===deck.cards[deck.index].id);break;case'focus':if(focusRemaining<=0)focusRemaining=1500;focusOn=!focusOn;render();break;case'export':{save();const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`toeic700-backup-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('已匯出學習紀錄。');break}}
});
document.addEventListener('change',e=>{lastActive=Date.now();if(e.target.id==='audio-rate')$('#speech-audio').playbackRate=Number(e.target.value);if(e.target.id==='word-filter'){filter=e.target.value;render()}if(e.target.id==='due-only'){dueOnly=e.target.checked;render()}if(e.target.id==='goal-select'){state.goal=Number(e.target.value);save();render()}if(e.target.id==='import-file'){const file=e.target.files[0];if(!file)return;if(file.size>5e6){toast('備份檔過大，請選擇 5 MB 以下的 JSON。');return}file.text().then(text=>{const imported=normalize(JSON.parse(text));if(!window.confirm('匯入會取代目前瀏覽器的學習紀錄。建議先匯出目前紀錄。確定匯入嗎？'))return;state=imported;save();render();toast('備份已匯入。')}).catch(()=>toast('備份檔格式有誤，現有紀錄未變更。'))}});
document.addEventListener('input',e=>{lastActive=Date.now();if(e.target.id==='word-search'){if(e.isComposing)return;search=e.target.value;const pos=e.target.selectionStart;render();const inp=$('#word-search');inp.focus();if(pos!==null)inp.setSelectionRange(pos,pos)}});
['pointerdown','keydown','scroll'].forEach(event=>document.addEventListener(event,()=>lastActive=Date.now(),{passive:true}));
let lastTick=Date.now();setInterval(()=>{const now=Date.now(),elapsed=Math.min(5,(now-lastTick)/1000);lastTick=now;if(document.visibilityState==='visible'&&now-lastActive<120000){day().seconds+=elapsed;timerTicks++;if(timerTicks%15===0)save()}if(focusOn&&document.visibilityState==='visible'){focusRemaining=Math.max(0,focusRemaining-elapsed);const label=$('#focus-label');if(label)label.textContent=`專注中 ${String(Math.floor(focusRemaining/60)).padStart(2,'0')}:${String(Math.floor(focusRemaining%60)).padStart(2,'0')}`;if(focusRemaining<=0){focusOn=false;toast('25 分鐘專注完成！休息一下，再繼續。')}}},1000);
document.addEventListener('visibilitychange',()=>{lastTick=Date.now();if(document.visibilityState==='hidden')save()});window.addEventListener('pagehide',()=>{save();halt()});
render();
})();
